/**
 * Pinterest / OG pin helpers: theme rotation, slug validation, feed catalog.
 * Pin images are generated by /api/og/pin; this module stays free of JSX.
 */
import { SITUATIONS } from "@/data/moms-bible/situations";
import { getSituationSeo } from "@/data/moms-bible/situation-seo";
import {
  FAITH_HUB,
  FAITH_SEO_CARDS,
  faithPageSeo,
  getFaithSeoCard,
  getSaintSeoCard,
  SAINTS_HUB,
  SAINT_SEO_CARDS,
  saintPageSeo,
} from "@/lib/seo/card-seo";
import { sundayMassWorksheetPath } from "@/lib/seo/sunday-mass-worksheets";
import { keyToSlug, sheetDescription, slugToKey } from "@/lib/resource/sheets";
import { getSiteUrl } from "@/lib/site-url";
import { getSundaySheet, listSundaySheetKeys } from "@/lib/sunday-sheet-content";

export const PIN_TYPES = ["worksheet", "saint", "faith", "verse"] as const;
export type PinType = (typeof PIN_TYPES)[number];

export const PIN_THEME_IDS = ["peach", "rose", "sage", "sky"] as const;
export type PinThemeId = (typeof PIN_THEME_IDS)[number];

export type PinTheme = {
  id: PinThemeId;
  background: string;
  panel: string;
  accent: string;
  ink: string;
  muted: string;
  badge: string;
};

/** Warm pastels matching Mom's Bible / worksheet pages (not neon). */
export const PIN_THEMES: Record<PinThemeId, PinTheme> = {
  peach: {
    id: "peach",
    background: "#fff3e6",
    panel: "#ffffff",
    accent: "#c9773a",
    ink: "#1f2937",
    muted: "#6b7280",
    badge: "#fde6c8",
  },
  rose: {
    id: "rose",
    background: "#fce8ef",
    panel: "#ffffff",
    accent: "#b85c7a",
    ink: "#1f2937",
    muted: "#6b7280",
    badge: "#f6d5e2",
  },
  sage: {
    id: "sage",
    background: "#e8f0e6",
    panel: "#ffffff",
    accent: "#5a7d5a",
    ink: "#1f2937",
    muted: "#6b7280",
    badge: "#d5e5d2",
  },
  sky: {
    id: "sky",
    background: "#e8f2f8",
    panel: "#ffffff",
    accent: "#c9a227",
    ink: "#1f2937",
    muted: "#6b7280",
    badge: "#dceaf4",
  },
};

export type PinContent = {
  type: PinType;
  slug: string;
  title: string;
  subtitle: string;
  description: string;
  pagePath: string;
  theme: PinThemeId;
};

export function isPinType(value: string): value is PinType {
  return (PIN_TYPES as readonly string[]).includes(value);
}

export function isPinThemeId(value: string): value is PinThemeId {
  return (PIN_THEME_IDS as readonly string[]).includes(value);
}

function hashTheme(type: string, slug: string): PinThemeId {
  let h = 0;
  const s = `${type}:${slug}`;
  for (let i = 0; i < s.length; i++) h = (Math.imul(31, h) + s.charCodeAt(i)) | 0;
  return PIN_THEME_IDS[Math.abs(h) % PIN_THEME_IDS.length]!;
}

/** Resolve a validated pin target from type+slug. Unknown → null (404). */
export function resolvePin(typeRaw: string, slugRaw: string, themeOverride?: string | null): PinContent | null {
  const type = typeRaw.trim();
  const slug = slugRaw.trim();
  if (!isPinType(type) || !slug) return null;
  const theme =
    themeOverride && isPinThemeId(themeOverride) ? themeOverride : hashTheme(type, slug);

  if (type === "worksheet") {
    const key = slugToKey(slug);
    const sheet = key ? getSundaySheet(key) : null;
    if (!key || !sheet || keyToSlug(key) !== slug) return null;
    return {
      type,
      slug,
      title: sheet.liturgicalName,
      subtitle: sheet.gospelRef,
      description: sheetDescription(sheet),
      pagePath: sundayMassWorksheetPath(key),
      theme,
    };
  }

  if (type === "saint") {
    const card = getSaintSeoCard(slug);
    if (!card) return null;
    const seo = saintPageSeo(card);
    return {
      type,
      slug,
      title: card.title,
      subtitle: card.when ? `Feast / memorial: ${card.when}` : card.set,
      description: seo.description,
      pagePath: `${SAINTS_HUB}/${card.slug}`,
      theme,
    };
  }

  if (type === "faith") {
    const card = getFaithSeoCard(slug);
    if (!card) return null;
    const seo = faithPageSeo(card);
    return {
      type,
      slug,
      title: card.title,
      subtitle: `${card.cat} · ${card.set}`,
      description: seo.description,
      pagePath: `${FAITH_HUB}/${card.slug}`,
      theme,
    };
  }

  // verse
  const seo = getSituationSeo(slug);
  const situation = SITUATIONS.find((s) => s.key === slug);
  if (!seo || !situation) return null;
  const firstRef = situation.refs[0]?.label ?? "Catholic Scripture for kids";
  return {
    type,
    slug,
    title: seo.h1,
    subtitle: firstRef,
    description: seo.description,
    pagePath: `/bible-verses-for-kids/${slug}`,
    theme,
  };
}

/** Relative pin image path (resolved via metadataBase / getSiteUrl). */
export function pinImagePath(type: PinType, slug: string): string {
  return `/api/og/pin?type=${encodeURIComponent(type)}&slug=${encodeURIComponent(slug)}`;
}

export function pinOgImage(type: PinType, slug: string, alt: string) {
  return {
    url: pinImagePath(type, slug),
    width: 1000,
    height: 1500,
    alt,
  } as const;
}

export function absolutePinImageUrl(type: PinType, slug: string): string {
  return `${getSiteUrl()}${pinImagePath(type, slug)}`;
}

export function absolutePageUrl(pagePath: string): string {
  const base = getSiteUrl();
  return `${base}${pagePath.startsWith("/") ? pagePath : `/${pagePath}`}`;
}

/**
 * Stable catalog for the Pinterest RSS rotator.
 * Order: Advent worksheets → 15 verse moments → other worksheets → saints → faith.
 */
export function buildPinterestCatalog(): PinContent[] {
  const keys = listSundaySheetKeys();
  const advent = keys.filter((k) => k.includes("_ADV")).sort((a, b) => a.localeCompare(b, "en", { numeric: true }));
  const other = keys.filter((k) => !k.includes("_ADV")).sort((a, b) => a.localeCompare(b, "en", { numeric: true }));

  const out: PinContent[] = [];
  for (const key of advent) {
    const pin = resolvePin("worksheet", keyToSlug(key));
    if (pin) out.push(pin);
  }
  for (const s of SITUATIONS) {
    if (!getSituationSeo(s.key)) continue;
    const pin = resolvePin("verse", s.key);
    if (pin) out.push(pin);
  }
  for (const key of other) {
    const pin = resolvePin("worksheet", keyToSlug(key));
    if (pin) out.push(pin);
  }
  for (const c of SAINT_SEO_CARDS) {
    const pin = resolvePin("saint", c.slug);
    if (pin) out.push(pin);
  }
  for (const c of FAITH_SEO_CARDS) {
    const pin = resolvePin("faith", c.slug);
    if (pin) out.push(pin);
  }
  return out;
}

export const PINS_PER_DAY = 4;

/** UTC day index (days since Unix epoch). */
export function utcDayIndex(date: Date = new Date()): number {
  return Math.floor(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()) / 86_400_000);
}

/** Deterministic 4 pins for a UTC calendar day (same day → same items). */
export function pinsForUtcDate(date: Date = new Date()): PinContent[] {
  const catalog = buildPinterestCatalog();
  if (catalog.length === 0) return [];
  const start = (utcDayIndex(date) * PINS_PER_DAY) % catalog.length;
  const items: PinContent[] = [];
  for (let i = 0; i < Math.min(PINS_PER_DAY, catalog.length); i++) {
    items.push(catalog[(start + i) % catalog.length]!);
  }
  return items;
}

/** Seconds until next UTC midnight (for Cache-Control max-age). */
export function secondsUntilNextUtcMidnight(now: Date = new Date()): number {
  const next = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + 1);
  return Math.max(60, Math.floor((next - now.getTime()) / 1000));
}

/** Label shown on the pin badge. */
export function pinTypeLabel(type: PinType): string {
  switch (type) {
    case "worksheet":
      return "Sunday Mass Worksheet";
    case "saint":
      return "Catholic Saint for Kids";
    case "faith":
      return "Catholic Faith for Kids";
    case "verse":
      return "Bible Verses for Kids";
  }
}

